const DB_NAME = "fileRepositoryDB";
const DB_VERSION = 1;
const STORE_NAME = "files";
let db;
const initDB = () => {
  return new Promise((resolve, reject) => {
    if (db) {
      return resolve(true);
    }
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onerror = (event) => {
      console.error("IndexedDB error:", request.error);
      reject(false);
    };
    request.onsuccess = (event) => {
      db = event.target.result;
      resolve(true);
    };
    request.onupgradeneeded = (event) => {
      const database = event.target.result;
      if (!database.objectStoreNames.contains(STORE_NAME)) {
        database.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };
  });
};
const addFile = (file, folderId, name) => {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], "readwrite");
    const store = transaction.objectStore(STORE_NAME);
    const id = v4();
    const fileRecord = { id, name, folderId, content: file };
    const request = store.add(fileRecord);
    request.onsuccess = () => {
      resolve(id);
    };
    request.onerror = () => {
      console.error("Error adding file:", request.error);
      reject(request.error);
    };
  });
};
const getFile = (id) => {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], "readonly");
    const store = transaction.objectStore(STORE_NAME);
    const request = store.get(id);
    request.onsuccess = () => {
      resolve(request.result);
    };
    request.onerror = () => {
      console.error("Error getting file:", request.error);
      reject(request.error);
    };
  });
};
const getAllFiles = () => {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], "readonly");
    const store = transaction.objectStore(STORE_NAME);
    const request = store.openCursor();
    const files = [];
    request.onsuccess = (event) => {
      const cursor = event.target.result;
      if (cursor) {
        const { id, name, folderId } = cursor.value;
        files.push({ id, name, folderId });
        cursor.continue();
      } else {
        resolve(files);
      }
    };
    request.onerror = () => {
      console.error("Error getting all files:", request.error);
      reject(request.error);
    };
  });
};
const deleteFile = (id) => {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction([STORE_NAME], "readwrite");
    const store = transaction.objectStore(STORE_NAME);
    const request = store.delete(id);
    request.onsuccess = () => {
      resolve();
    };
    request.onerror = () => {
      console.error("Error deleting file:", request.error);
      reject(request.error);
    };
  });
};
